import{_ as s,l as t,o as e,c as n,v as r,p as l,x as o,d as p,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Harrison–Kreps 异质信念","description":"","frontmatter":{"title":"Harrison–Kreps 异质信念","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/harrison-kreps-speculation.md","filePath":"econ/harrison-kreps-speculation.md","lastUpdated":1789023840000}'),c={name:"econ/harrison-kreps-speculation.md"};function h(B,a,_,m,A,u){const i=t("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="harrison–kreps-异质信念" tabindex="-1">Harrison–Kreps 异质信念 <a class="header-anchor" href="#harrison–kreps-异质信念" aria-label="Permalink to &quot;Harrison–Kreps 异质信念&quot;">​</a></h1><div class="epigraph"><p>不能卖空时，价格由最乐观的人决定；他还愿意付一笔溢价，因为可以把资产再卖给明天更乐观的人。</p><footer>—— Harrison and Kreps, Speculative Investor Behavior in a Stock Market with Heterogeneous Expectations, QJE 1978</footer></div><p><a href="/econ/disposition-effect">上一课</a>的参考点在成本。本课缺口换成信念异质：即使每个人内部时间一致、按期望效用定价，只要信念不同且卖空受限，价格可以高于任何一个人的持有价值。不重写损失厌恶。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公共信息下 <a href="/econ/emh">EMH</a> 常默认共同先验。Harrison 与 Kreps（1978）：投资者对股息过程持不同主观信念，禁止卖空。当前持有者的价值 = 自己吃股息的价值 + <strong>转售期权</strong>（卖给未来更乐观者）。价格可以严格高于所有人的最高基本面估值。投机溢价来自再售，不是来自 \\(v\\) 的拐折。缺口是给泡沫一个不依赖前景理论的理论核。</p><p><span class="marginnote">Miller（1977）已经指出卖空限制下价格反映乐观者。Harrison–Kreps 把动态转售加进去，溢价可以随时间变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离散时间，异质马尔可夫信念，卖空约束。动态规划：持有者每期选择继续持有或卖给当期最乐观的人。均衡价格过程被最乐观的边际买者决定，并含期权项。比较静态：信念越散、越可能轮流当最乐观，转售期权越贵。</p>',8)),(e(),l(d,null,{default:o(()=>[E(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HET%5B%22%E5%BC%82%E8%B4%A8%E4%BF%A1%E5%BF%B5%22%5D%20--%3E%20SS%5B%22%E5%8D%96%E7%A9%BA%E9%99%90%E5%88%B6%22%5D%0A%20%20SS%20--%3E%20OPT%5B%22%E8%BE%B9%E9%99%85%E4%B9%B0%E8%80%85%E6%98%AF%E6%9C%80%E4%B9%90%E8%A7%82%E8%80%85%22%5D%0A%20%20OPT%20--%3E%20RESALE%5B%22%E8%BD%AC%E5%94%AE%E6%9C%9F%E6%9D%83%3A%20%E4%BB%B7%E6%A0%BC%E9%AB%98%E4%BA%8E%E4%BB%BB%E4%BD%95%E4%BA%BA%E7%9A%84%E5%9F%BA%E6%9C%AC%E9%9D%A2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>本课不把意见分歧写成限价簿上的买卖档。那是协议；这里是谁被允许持有负仓。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是约束下的期权。悲观者无法把负仓拿满，其信息不能对称地压低价格。乐观者支付的不只是股息，还有「明天也许有人比我更乐观」的彩票。这与 DSSW 不同：不必有人系统性地错，只要持续不同意且不能卖空。与 DHS 过度自信相容：过度精确加大分歧，放大转售期权——Scheinkman–Xiong 下一课把这句话做实。</p><p>共同先验加不同信息通常会通过价格学习。Harrison–Kreps 允许对数据生成过程根本不同意，卖空一关，边际定价权交给当期最乐观者。Miller 的静态版没有期权项；动态版让泡沫随「谁明天更乐观」的概率而涨。本课 \\(p\\) 仍是均衡价格，不是买卖档。主干在簿的交接处停，这里补的是持有权约束，不是队列。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>允许充分卖空，转售期权消失，价格回到某种加权平均信念。共同先验加不同信息会回到理性预期学习，不一定有泡沫。本课不处理内生信息获取。理性泡沫（Tirole）是另一条：共同信念下的爆炸解，更后一课。</p><p>后课默认：投机溢价 = 转售期权；换手是期权被行使的痕迹。</p><p>卖空限制下边际买者是最乐观者，价格含转售期权，可高于所有人的基本面估值。</p><p>不必有人系统错，只要持续不同意。共同先验加学习通常会收敛；此处允许根本不同意。</p><p><span class="marginnote">内生信息获取本课不处理；理性泡沫是共同信念下的另一支。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>卖空限制下，价格由乐观者加转售期权决定，可高于所有基本面估值。</li><li>不需要前景理论，不需要噪声的随机需求。</li><li>分歧加约束是泡沫的一条理性投机核。</li><li>Miller 静态版没有期权项。</li><li>充分卖空关掉溢价。</li><li>出处：Harrison and Kreps, <em>QJE</em> 1978。</li></ul>',12))])}const T=s(c,[["render",h]]);export{S as __pageData,T as default};
